  "claim": {
    "component_id": "C011.component",
    "value": "For accounts with a stated next roster opportunity, follow-up should extend through that opportunity plus a predeclared grace period.",
    "scope": "The roster-linked follow-up rule; the grace-period duration is unspecified. Its precedence relative to the general predeclared follow-up limits is not stated.",
